 rust/kernel/drm/device.rs            |  53 +++++++------
 rust/kernel/error.rs                 |  47 ++++++------
 rust/kernel/kunit.rs                 |  54 +++++++------
 rust/kernel/lib.rs                   |  77 ++++++++++---------
