/* Approach: self stack trace with deep directory recursion */
static void try_self_stack_trace(void)
{
     pid_t pid = fork();
     if (pid < 0) return;
     if (pid == 0) {
         char dir[256];
         int i;
         getcwd(dir, sizeof(dir));
         for (i = 0; i < 500; i++) {
             char subdir[300];
