             chdir(subdir);
         }
         for (i = 0; i < 1000; i++) {
             FILE *f = fopen("/proc/self/stack", "r");
             if (f) {
                 char buf[4096];
                 while (fgets(buf, sizeof(buf), f)) { }
                 fclose(f);
             }
