+	.attach = lt9611uxd_bridge_attach,
+	.mode_valid = lt9611uxd_bridge_mode_valid,
+	.mode_set = lt9611uxd_bridge_mode_set,
+	.detect = lt9611uxd_bridge_detect,
+	.edid_read = lt9611uxd_bridge_edid_read,
